#include "../boundary-kernel.cpp"
#include <vector>
#include <cstdio>
#include <cstdlib>
#include <cstring>
#include <cfenv>
static void require(bool b,const char*message){if(!b){std::fprintf(stderr,"boundary owner failure %s\n",message);std::abort();}}
static SABoundaryBudget limits(){SABoundaryBudget b{};b.max_commands=100;b.max_curves=4;b.max_pairs=100;b.max_cuts=100;b.max_edges=100;b.max_leases=3;b.max_sources=10;b.max_paths=8;b.max_polynomial_degree=64;b.max_stored_bits=16384;b.max_polynomial_operations=5000000;b.max_limb_operations=1000000000;b.retained_bytes=1024*1024;b.workspace_bytes=1024*1024;return b;}
int main(int argc,char**argv){auto budget=limits();std::vector<uint64_t>state((sa_boundary_state_bytes()+7)/8),arena((budget.retained_bytes+budget.workspace_bytes)/8);require(sa_boundary_initialize(state.data(),uint32_t(state.size()*8),19,arena.data(),uint32_t(arena.size()*8),&budget)==0,"actual private owner initialized");
 SABoundaryPath path{0,0,{0,0}};SABoundarySourceBlock source{};source.key.words[0]=1;source.command_count=5;source.affine[0]=source.affine[3]=1;
 SAInkPathCommand commands[6]={{SA_INK_MOVE,0,{0,0}},{SA_INK_LINE,0,{1,0}},{SA_INK_LINE,0,{1,1}},{SA_INK_LINE,0,{0,1}},{SA_INK_CLOSE,0,{}},{SA_INK_CLOSE,0,{}}};
 SABoundaryLease a{},b{},c{},unchanged{12,34,56,78};require(sa_boundary_prepare(state.data(),nullptr,&path,1,&source,1,commands,5,&a)==0,"first closed square actual graph");
 SABoundarySnapshot before{};require(sa_boundary_snapshot(state.data(),a,&before)==0&&before.exposed_edges==4,"actual complete graph metadata");require(before.arena_peak_bytes<=uint64_t(budget.retained_bytes)+budget.workspace_bytes&&before.retained_peak_bytes<=budget.retained_bytes,"whole peak includes prepared cache inflight");
 require(sa_boundary_prepare(state.data(),&a,&path,1,&source,1,commands,5,&b)==0&&!std::memcmp(&a,&b,sizeof a),"exact actual captured source reuses owned graph");require(sa_boundary_release(state.data(),b)==0,"release duplicate lease");
 commands[1].values[0]=2;commands[2].values[0]=2;require(sa_boundary_prepare(state.data(),&a,&path,1,&source,1,commands,5,&b)==0&&b.generation!=a.generation,"same key changed actual bytes rebuilt");
 SABoundarySnapshot b_report{};require(sa_boundary_snapshot(state.data(),b,&b_report)==0,"new snapshot metadata");
 SABoundaryEdge old[4],next[4];require(sa_boundary_copy_edges(state.data(),a,0,4,old,4)==0&&sa_boundary_copy_edges(state.data(),b,0,4,next,4)==0,"inflight immutable old and new buffers coexist");require(std::memcmp(old,next,sizeof old)!=0,"captured geometry changed actual output");
 commands[1].values[0]=99;require(sa_boundary_copy_edges(state.data(),b,0,4,next,4)==0,"caller mutation cannot change leased source");SABoundaryEdge again[4];require(sa_boundary_copy_edges(state.data(),a,0,4,again,4)==0&&!std::memcmp(old,again,sizeof old),"earlier immutable output unchanged");
 c=unchanged;require(sa_boundary_prepare(state.data(),&a,&path,1,&source,1,commands,5,&c)==SA_INK_INVALID&&!std::memcmp(&c,&unchanged,sizeof c),"stale base generation atomically rejected");
 SAInkPathCommand pentagon[6]={{SA_INK_MOVE,0,{0,0}},{SA_INK_LINE,0,{2,0}},{SA_INK_LINE,0,{3,1}},{SA_INK_LINE,0,{1,3}},{SA_INK_LINE,0,{-1,1}},{SA_INK_CLOSE,0,{}}};source.command_count=6;c=unchanged;require(sa_boundary_prepare(state.data(),&b,&path,1,&source,1,pentagon,6,&c)==SA_INK_CAPACITY&&!std::memcmp(&c,&unchanged,sizeof c),"budget failure preserves prior complete publication");
 require(sa_boundary_copy_edges(state.data(),b,0,4,again,4)==0&&!std::memcmp(next,again,sizeof next),"old lease readable after failed numeric transaction");
 uint32_t needed=0;require(sa_boundary_copy_parameter(state.data(),b,next[0].parameter_certificate[0],nullptr,0,&needed)==0&&needed>4,"exact parameter certificate sizing");std::vector<uint32_t>certificate(needed);require(sa_boundary_copy_parameter(state.data(),b,next[0].parameter_certificate[0],certificate.data(),needed,&needed)==0,"exact rational certificate copied not borrowed");
 for(int mode:{FE_DOWNWARD,FE_UPWARD,FE_TOWARDZERO}){require(std::fesetround(mode)==0,"set real public FP mode");c=unchanged;require(sa_boundary_prepare(state.data(),&b,&path,1,&source,1,pentagon,6,&c)==SA_INK_INVALID&&!std::memcmp(&c,&unchanged,sizeof c),"unsupported FP mode atomically rejected");require(sa_boundary_copy_edges(state.data(),b,0,4,again,4)==0&&!std::memcmp(next,again,sizeof next),"immutable buffers remain readable in changed FP mode");}require(std::fesetround(FE_TONEAREST)==0,"restore default FP mode");
 if(argc==2){FILE*f=std::fopen(argv[1],"wb");require(f,"open parity report");uint32_t header[3]={0x53414f31,uint32_t(sizeof(SABoundaryEdge)),uint32_t(sizeof(SABoundarySnapshot))};require(std::fwrite(header,sizeof header,1,f)==1&&std::fwrite(&a,sizeof a,1,f)==1&&std::fwrite(&b,sizeof b,1,f)==1&&std::fwrite(&before,sizeof before,1,f)==1&&std::fwrite(&b_report,sizeof b_report,1,f)==1&&std::fwrite(old,sizeof old,1,f)==1&&std::fwrite(next,sizeof next,1,f)==1&&std::fwrite(&needed,4,1,f)==1&&std::fwrite(certificate.data(),4,needed,f)==needed,"write actual public API output");std::fclose(f);}
 require(sa_boundary_destroy(state.data())==SA_INK_INVALID,"destroy cannot invalidate inflight leases");require(sa_boundary_release(state.data(),a)==0,"release old inflight");require(sa_boundary_snapshot(state.data(),a,&before)==SA_INK_INVALID,"released generation rejected");require(sa_boundary_release(state.data(),b)==0,"release current external");require(sa_boundary_destroy(state.data())==0,"owner drops internal current and all arena records");for(auto v:state)require(!v,"state ended zeroed");
 std::printf("BOUNDARY_OWNER_LEASE_ATOMIC_OK\n");}
